{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "The closest analogue (Morgan 0.4167) has an oral bioavailability of approximately 20–25% in patients, which is at or above the 20% threshold and supports high bioavailability, though borderline.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Brigatinib, a structurally related aminopyrimidine/piperazine kinase inhibitor, has an absolute oral bioavailability of 46% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Imatinib, containing a piperazine and aminopyrimidine motif, is almost completely absorbed with 98% absolute bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Brepocitinib, a related heteroaromatic amine, has an estimated absolute bioavailability of 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Abemaciclib, a piperazine-containing kinase inhibitor, has an absolute oral bioavailability of 45% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Risdiplam, a heteroaromatic piperazine analogue, has high oral bioavailability due to complete absorption and negligible first-pass extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "TFMPP, a simple phenylpiperazine, showed low bioavailability in humans, but its low structural similarity limits transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a piperazine-containing heteroaromatic kinase-inhibitor-like molecule. Multiple structurally related analogues with moderate-to-high transferability show absolute oral bioavailability of 45–98%, and the closest analogue is at the 20–25% boundary. The only low-bioavailability analogue is a much smaller phenylpiperazine with low transferability. Therefore, F >=20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The closest analogue has borderline bioavailability (20–25%), leaving uncertainty near the threshold.",
    "Metabolic stability, transporter effects, and solubility of the query are not directly measured.",
    "Human pharmacokinetic data for the exact query scaffold are unavailable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

